/*
 * The four conformance tables, over the shared text_bid_dpd corpus.
 *
 * The vectors are read straight out of resources/text_bid_dpd -- the
 * decimal128-resources submodule -- and were generated by the decimal128-c
 * engine through its public API. That engine reaches its answers by different
 * algorithms than this codec does, so agreement is a cross-check rather than a
 * tautology.
 *
 *   T1 DECODE  bid -> text and dpd -> text          (100, noncanonical)
 *   T2 ENCODE  text -> bid and text -> dpd          (100)
 *   T3 PARSE   input text -> bits, both formats     (parse, 1,061 rows)
 *   T4 ERROR   malformed input text -> rejection    (error, 173 rows)
 *
 * Plus the cross-format assertion: for every row both encodings must render to
 * the same text. That is the strongest property the corpus encodes.
 *
 * The fifth table, canonical, is 84,783 rows of mostly common-path volume and
 * runs as TestCanonicalTableDecodesAndReEncodes at the bottom of this file.
 *
 * This is a black-box test file: it is compiled as an external test package, so
 * it can reach only the four exported functions -- the same surface a consumer
 * has. Nothing here can touch a package-private helper even by accident.
 */

package decimal128textcodec_test

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	codec "github.com/migueldecimal128/decimal128-text-codec-go"
)

// ---------------------------------------------------------------------------
// The tables
// ---------------------------------------------------------------------------

// T1: every row's two encodings must render to the expected text.
func TestHundredDecodes(t *testing.T) {
	rows := loadCorpus(t, corpusHundred)
	assertRowCount(t, rows, 100, corpusHundred)
	runDecodeTable(t, rows, "100")
}

// T2: and the text must encode back to the same bits.
func TestHundredReEncodes(t *testing.T) {
	rows := loadCorpus(t, corpusHundred)
	assertRowCount(t, rows, 100, corpusHundred)
	runEncodeTable(t, rows, "100")
}

// One-way rows: both encodings decode to the text, but at least one is a bit
// pattern the canonical encoder would never emit, so re-encoding is
// deliberately not asserted.
func TestNonCanonicalEncodingsRenderCorrectly(t *testing.T) {
	rows := loadCorpus(t, corpusNonCanonical)
	assertRowCount(t, rows, 1267, corpusNonCanonical)
	runDecodeTable(t, rows, "noncanonical")
}

// T3: the only table that reaches the rounding surface at all.
func TestParseVectorsProduceBothEncodings(t *testing.T) {
	rows := loadCorpus(t, corpusParse)
	assertRowCount(t, rows, 1061, corpusParse)
	for _, row := range rows {
		bidHi, bidLo, err := codec.Bid128Parse(row.text)
		if err != nil {
			t.Errorf("parse line %d: bid rejected <%s>: %v", row.lineNumber, row.text, err)
		} else if bidHi != row.bidHi || bidLo != row.bidLo {
			t.Errorf("parse line %d: bid <%s> gave %s, expected %s",
				row.lineNumber, row.text, hex32(bidHi, bidLo), row.bidHex())
		}
		dpdHi, dpdLo, err := codec.Dpd128Parse(row.text)
		if err != nil {
			t.Errorf("parse line %d: dpd rejected <%s>: %v", row.lineNumber, row.text, err)
		} else if dpdHi != row.dpdHi || dpdLo != row.dpdLo {
			t.Errorf("parse line %d: dpd <%s> gave %s, expected %s",
				row.lineNumber, row.text, hex32(dpdHi, dpdLo), row.dpdHex())
		}
	}
}

/*
 * T4: malformed input. Both formats must reject, must agree on the message, and
 * must still have produced the canonical positive quiet NaN -- the corpus
 * carries that pattern in its bits columns precisely so a port can assert the
 * returned value and not merely the rejection. Here the returning itself is
 * guaranteed by the signature; what the assertion adds is that the value
 * returned is the right one.
 */
func TestErrorVectorsAreRejectedByBothFormats(t *testing.T) {
	rows := loadCorpus(t, corpusError)
	assertRowCount(t, rows, 173, corpusError)
	for _, row := range rows {
		bidHi, bidLo, bidErr := codec.Bid128Parse(row.text)
		dpdHi, dpdLo, dpdErr := codec.Dpd128Parse(row.text)
		if bidErr == nil {
			t.Errorf("error line %d: bid ACCEPTED <%s>, corpus says %s", row.lineNumber, row.text, row.status)
		}
		if dpdErr == nil {
			t.Errorf("error line %d: dpd ACCEPTED <%s>, corpus says %s", row.lineNumber, row.text, row.status)
		}
		if bidErr != nil && dpdErr != nil && bidErr.Error() != dpdErr.Error() {
			t.Errorf("error line %d: the formats disagree on <%s>: <%v> vs <%v>",
				row.lineNumber, row.text, bidErr, dpdErr)
		}
		if bidHi != row.bidHi || bidLo != row.bidLo {
			t.Errorf("error line %d: bid <%s> left %s, expected %s",
				row.lineNumber, row.text, hex32(bidHi, bidLo), row.bidHex())
		}
		if dpdHi != row.bidHi || dpdLo != row.bidLo {
			t.Errorf("error line %d: dpd <%s> left %s, expected %s",
				row.lineNumber, row.text, hex32(dpdHi, dpdLo), row.bidHex())
		}
	}
}

/*
 * The reader itself. parse and error quote their text column, and the four rows
 * below are exactly the ones a naive comma split corrupts while still passing
 * -- a mangled malformed input fails to parse either way.
 */
func TestQuotedColumnRoundTrips(t *testing.T) {
	rows := loadCorpus(t, corpusError)
	texts := make(map[string]bool, len(rows))
	for _, row := range rows {
		texts[row.text] = true
	}
	if !texts[""] {
		t.Error("the empty-string row was lost")
	}
	if !anyText(texts, func(s string) bool { return strings.HasPrefix(s, " ") }) {
		t.Error("a leading-space row was lost")
	}
	if !anyText(texts, func(s string) bool { return strings.HasSuffix(s, " ") }) {
		t.Error("a trailing-space row was lost")
	}
	if !anyText(texts, func(s string) bool { return strings.Contains(s, ",") }) {
		t.Error("an embedded-comma row was lost")
	}
}

/*
 * The full canonical table, read from the same submodule as the rest. It is a
 * test of its own only because it is two orders of magnitude bigger than the
 * other four put together, not because it is optional.
 */
func TestCanonicalTableDecodesAndReEncodes(t *testing.T) {
	rows := loadCorpus(t, corpusCanonical)
	assertRowCount(t, rows, 84783, corpusCanonical)
	runDecodeTable(t, rows, "canonical")
	runEncodeTable(t, rows, "canonical")
}

// ---------------------------------------------------------------------------
// The two table runners
// ---------------------------------------------------------------------------

// Every row: both encodings must render to the expected text, and therefore to
// each other.
func runDecodeTable(t *testing.T, rows []corpusRow, label string) {
	t.Helper()
	var buf [codec.MaxLen]byte
	for _, row := range rows {
		n := codec.Bid128ToAscii(&buf, row.bidHi, row.bidLo)
		if bidText := string(buf[:n]); bidText != row.text {
			t.Errorf("%s line %d: bid #%s rendered <%s>, expected <%s>",
				label, row.lineNumber, row.bidHex(), bidText, row.text)
		}
		n = codec.Dpd128ToAscii(&buf, row.dpdHi, row.dpdLo)
		if dpdText := string(buf[:n]); dpdText != row.text {
			t.Errorf("%s line %d: dpd #%s rendered <%s>, expected <%s>",
				label, row.lineNumber, row.dpdHex(), dpdText, row.text)
		}
	}
}

// Round-trippable rows: the text must encode back to the same bits.
func runEncodeTable(t *testing.T, rows []corpusRow, label string) {
	t.Helper()
	for _, row := range rows {
		bidHi, bidLo, err := codec.Bid128Parse(row.text)
		if err != nil {
			t.Errorf("%s line %d: bid rejected <%s>: %v", label, row.lineNumber, row.text, err)
		} else if bidHi != row.bidHi || bidLo != row.bidLo {
			t.Errorf("%s line %d: bid <%s> gave %s, expected %s",
				label, row.lineNumber, row.text, hex32(bidHi, bidLo), row.bidHex())
		}
		dpdHi, dpdLo, err := codec.Dpd128Parse(row.text)
		if err != nil {
			t.Errorf("%s line %d: dpd rejected <%s>: %v", label, row.lineNumber, row.text, err)
		} else if dpdHi != row.dpdHi || dpdLo != row.dpdLo {
			t.Errorf("%s line %d: dpd <%s> gave %s, expected %s",
				label, row.lineNumber, row.text, hex32(dpdHi, dpdLo), row.dpdHex())
		}
	}
}

func anyText(texts map[string]bool, pred func(string) bool) bool {
	for s := range texts {
		if pred(s) {
			return true
		}
	}
	return false
}

// ---------------------------------------------------------------------------
// One row of a text_bid_dpd table: the text, the two encodings, and the status
// column the input-driven tables carry.
// ---------------------------------------------------------------------------

type corpusRow struct {
	text       string
	bidHi      uint64
	bidLo      uint64
	dpdHi      uint64
	dpdLo      uint64
	status     string
	lineNumber int
}

// The encoding as the corpus spells it: 32 uppercase hex digits.
func (r corpusRow) bidHex() string { return hex32(r.bidHi, r.bidLo) }
func (r corpusRow) dpdHex() string { return hex32(r.dpdHi, r.dpdLo) }

func hex32(hi, lo uint64) string { return fmt.Sprintf("%016X%016X", hi, lo) }

// Parse 32 hex digits, with or without a leading 0x.
func parseHex32(s string) (hi, lo uint64, ok bool) {
	body := s
	if strings.HasPrefix(body, "0x") || strings.HasPrefix(body, "0X") {
		body = body[2:]
	}
	if len(body) != 32 {
		return 0, 0, false
	}
	hi, err := strconv.ParseUint(body[:16], 16, 64)
	if err != nil {
		return 0, 0, false
	}
	lo, err = strconv.ParseUint(body[16:], 16, 64)
	if err != nil {
		return 0, 0, false
	}
	return hi, lo, true
}

// ---------------------------------------------------------------------------
// The shared conformance corpus, read from resources/text_bid_dpd -- the
// decimal128-resources submodule, mounted at the repo root the way every
// decimal128 port mounts it. Nothing is copied into this repo.
//
// The row counts are asserted by the tests, and that is not ceremony: the text
// column of parse and error is double-quoted with backslash escapes, because
// those tables must carry the empty string, a leading and a trailing space, an
// embedded comma, an embedded quote and an embedded backslash. The other three
// leave it bare. A naive comma split silently corrupts four rows and still
// passes, since a mangled malformed input fails to parse either way. The row
// count is what catches it.
//
// go test runs each test binary in its package's source directory, so the
// relative path is all this port needs -- the C port's compiled-in VECTOR_DIR,
// Swift's #filePath and C#'s [CallerFilePath] all exist to recover what Go
// hands over. An absolute DECIMAL128_RESOURCES still overrides it, for a runner
// that relocates the binary away from the tree it was built in.
// ---------------------------------------------------------------------------

const (
	corpusHundred      = "text_bid128_dpd128_100"
	corpusNonCanonical = "text_bid128_dpd128_noncanonical"
	corpusParse        = "text_bid128_dpd128_parse"
	corpusError        = "text_bid128_dpd128_error"
	corpusCanonical    = "text_bid128_dpd128_canonical"
)

// Where the loader looked, for an error message that names the fix.
const resourcesHint = "the decimal128-resources submodule is not checked out: " +
	"run `git submodule update --init --recursive`"

func corpusDirectory() string {
	if env := os.Getenv("DECIMAL128_RESOURCES"); env != "" {
		return filepath.Join(env, "text_bid_dpd")
	}
	return filepath.Join("resources", "text_bid_dpd")
}

// One table, read off the filesystem.
func loadCorpus(t *testing.T, name string) []corpusRow {
	t.Helper()
	path := filepath.Join(corpusDirectory(), name+".csv.txt")
	contents, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("%s could not be read (%v) -- %s", path, err, resourcesHint)
	}
	return parseTable(t, string(contents), name)
}

func assertRowCount(t *testing.T, rows []corpusRow, want int, name string) {
	t.Helper()
	if len(rows) != want {
		t.Fatalf("%s.csv.txt has %d rows, expected %d", name, len(rows), want)
	}
}

func parseTable(t *testing.T, contents, name string) []corpusRow {
	t.Helper()
	var rows []corpusRow
	for lineNumber, rawLine := range strings.Split(contents, "\n") {
		line := strings.TrimRight(rawLine, "\r")
		line = skipSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		var text string
		if strings.HasPrefix(line, "\"") {
			text, line = readQuoted(line)
		} else {
			text, line = readField(line)
		}
		bidField, line := readNextField(line)
		dpdField, line := readNextField(line)
		status, _ := readNextField(line)

		bidHi, bidLo, bidOK := parseHex32(bidField)
		dpdHi, dpdLo, dpdOK := parseHex32(dpdField)
		if !bidOK || !dpdOK {
			t.Fatalf("%s.csv.txt line %d: malformed hex columns <%s> <%s>",
				name, lineNumber+1, bidField, dpdField)
		}
		rows = append(rows, corpusRow{
			text:       text,
			bidHi:      bidHi,
			bidLo:      bidLo,
			dpdHi:      dpdHi,
			dpdLo:      dpdLo,
			status:     status,
			lineNumber: lineNumber + 1,
		})
	}
	return rows
}

// -- the reader, matching the C, Swift, Kotlin, Java and C# ports -------------

func skipSpace(s string) string {
	i := 0
	for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
		i++
	}
	return s[i:]
}

/*
 * One comma-delimited field, stopping at ',' or '#' or end of line, with
 * surrounding whitespace trimmed. Returns the field and the unconsumed rest.
 */
func readField(s string) (value, rest string) {
	start := skipSpace(s)
	end := 0
	for end < len(start) && start[end] != ',' && start[end] != '#' {
		end++
	}
	trim := end
	for trim > 0 && (start[trim-1] == ' ' || start[trim-1] == '\t') {
		trim--
	}
	return start[:trim], start[end:]
}

// Step over a field separator, then read the next field. Yields the empty
// string when the row has no further column.
func readNextField(s string) (value, rest string) {
	rest = skipSpace(s)
	if !strings.HasPrefix(rest, ",") {
		return "", rest
	}
	return readField(rest[1:])
}

// The quoted text column, honouring backslash escapes.
func readQuoted(s string) (value, rest string) {
	var out strings.Builder
	i := 1 // past the opening quote
	for i < len(s) && s[i] != '"' {
		c := s[i]
		i++
		if c == '\\' && i < len(s) {
			c = s[i]
			i++
		}
		out.WriteByte(c)
	}
	if i < len(s) && s[i] == '"' {
		i++
	}
	return out.String(), s[i:]
}
